<?php
declare(strict_types=1);
require dirname(__DIR__) . '/app/bootstrap.php';
$user = requireLogin();
require_once BASE_PATH . '/includes/rental-operations-common.php';
ro_require_permission('rentals.manage');
$pdo=Database::connection();
RentalOperations::refreshOverdueRentals($pdo);
if (is_post()) {
    ro_post_guard();
    try { $id=RentalOperations::createRental($pdo,(int)($_POST['agreement_id']??0),isset($user['user_id'])?(int)$user['user_id']:null); ro_flash('success','Rental opened. Complete the pickup record before handing over the vehicle.'); redirect('admin/rental-view.php?id='.$id); }
    catch(Throwable $e){ro_flash('danger',$e->getMessage());redirect('admin/rentals.php');}
}
$pageTitle='Rental Desk';$currentPage='rentals';
$ready=$pdo->query("SELECT a.agreement_id,a.agreement_number,a.reservation_id,c.first_name,c.last_name,v.make,v.model,v.registration_no,r.pickup_datetime,r.return_datetime FROM rental_agreements a JOIN reservations r ON r.reservation_id=a.reservation_id JOIN customers c ON c.customer_id=a.customer_id JOIN vehicles v ON v.vehicle_id=a.vehicle_id LEFT JOIN rentals x ON x.agreement_id=a.agreement_id WHERE a.status='signed' AND r.status='confirmed' AND x.rental_id IS NULL ORDER BY r.pickup_datetime")->fetchAll(PDO::FETCH_ASSOC);
$rentals=$pdo->query('SELECT r.rental_id,r.rental_number,r.status,r.actual_pickup_datetime,r.expected_return_datetime,r.actual_return_datetime,r.final_amount,r.pickup_mileage,r.return_mileage,c.first_name,c.last_name,v.make,v.model,v.registration_no,a.agreement_number FROM rentals r JOIN customers c ON c.customer_id=r.customer_id JOIN vehicles v ON v.vehicle_id=r.vehicle_id JOIN rental_agreements a ON a.agreement_id=r.agreement_id ORDER BY FIELD(r.status,\'overdue\',\'active\',\'scheduled\',\'inspected\',\'returned\',\'closed\',\'cancelled\'),r.expected_return_datetime ASC LIMIT 200')->fetchAll(PDO::FETCH_ASSOC);
require BASE_PATH . '/includes/header.php';require BASE_PATH . '/includes/rental-operations-nav.php';
?>
<div class="ro-shell"><section class="ro-page-heading"><div><span class="ro-kicker">VEHICLE HANDOVER</span><h1>Rental desk</h1><p>Open rentals from signed agreements, record pickup and return readings, and close the loop with inspections and billing.</p></div><div class="ro-heading-symbol"><i class="bi bi-car-front"></i></div></section>
<?php if($ready): ?><section class="ro-panel mb-4"><div class="ro-panel-head"><div><span class="ro-kicker">READY TO OPEN</span><h2>Signed agreements without a rental</h2></div><span class="ro-counter"><?= count($ready) ?> ready</span></div><div class="table-responsive"><table class="table ro-table align-middle"><thead><tr><th>Agreement</th><th>Customer</th><th>Vehicle</th><th>Pickup</th><th>Expected return</th><th></th></tr></thead><tbody><?php foreach($ready as $r): ?><tr><td><strong><?= e($r['agreement_number']) ?></strong></td><td><?= e($r['first_name'].' '.$r['last_name']) ?></td><td><?= e($r['make'].' '.$r['model']) ?><small class="d-block text-secondary"><?= e($r['registration_no']) ?></small></td><td><?= e(ro_date($r['pickup_datetime'])) ?></td><td><?= e(ro_date($r['return_datetime'])) ?></td><td><form method="post"><?= csrf_field() ?><input type="hidden" name="agreement_id" value="<?= (int)$r['agreement_id'] ?>"><button class="btn ro-btn-primary" type="submit"><i class="bi bi-plus-lg me-1"></i> Open rental</button></form></td></tr><?php endforeach; ?></tbody></table></div></section><?php endif; ?>
<section class="ro-panel"><div class="ro-panel-head"><div><span class="ro-kicker">FLEET ACTIVITY</span><h2>Rental records</h2></div><span class="ro-counter"><?= count($rentals) ?> records</span></div><?php if(!$rentals): ?><div class="ro-empty"><div class="ro-empty-icon"><i class="bi bi-key"></i></div><strong>No rental records yet</strong><p>Once an agreement is signed, it can be opened here.</p></div><?php else: ?><div class="table-responsive"><table class="table ro-table align-middle"><thead><tr><th>Rental</th><th>Customer</th><th>Vehicle</th><th>Status</th><th>Pickup</th><th>Expected return</th><th>Final amount</th><th></th></tr></thead><tbody><?php foreach($rentals as $r): ?><tr><td><strong><?= e($r['rental_number']) ?></strong><small class="d-block text-secondary"><?= e($r['agreement_number']) ?></small></td><td><?= e($r['first_name'].' '.$r['last_name']) ?></td><td><?= e($r['make'].' '.$r['model']) ?><small class="d-block text-secondary"><?= e($r['registration_no']) ?></small></td><td><?= ro_status_badge($r['status']) ?></td><td><?= e(ro_date($r['actual_pickup_datetime'],'Not picked up')) ?></td><td><?= e(ro_date($r['expected_return_datetime'])) ?></td><td><?= ro_money($r['final_amount']) ?></td><td><a class="btn btn-sm ro-btn-outline" href="<?= e(base_url('admin/rental-view.php?id='.(int)$r['rental_id'])) ?>">Manage <i class="bi bi-arrow-up-right"></i></a></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section></div>
<?php require BASE_PATH . '/includes/footer.php'; ?>
